const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Market capitalisation (market cap)","hi":"मार्केट कैप"},"def":{"en":"Share price multiplied by the number of shares outstanding. Companies are grouped as large, mid or small cap.","hi":"शेयर कीमत को बकाया शेयरों की संख्या से गुणा करने पर मिलने वाली कंपनी की कुल वैल्यू। कंपनियाँ लार्ज, मिड या स्मॉल कैप में बाँटी जाती हैं।"}},{"cat":"fundamental","term":{"en":"P/E ratio","hi":"P/E अनुपात"},"def":{"en":"Share price divided by earnings per share. It shows how much investors pay for each rupee of earnings.","hi":"शेयर कीमत को EPS से भाग देने पर प्राप्त अनुपात। यह दिखाता है कि निवेशक कमाई के हर रुपये के लिए कितना दे रहे हैं।"}},{"cat":"fundamental","term":{"en":"Book value","hi":"बुक वैल्यू"},"def":{"en":"Shareholders' equity divided by the number of shares: the accounting value per share.","hi":"शेयरधारक इक्विटी को शेयरों की संख्या से भाग देने पर प्रति शेयर लेखांकन मूल्य।"}},{"cat":"fundamental","term":{"en":"EV/EBITDA","hi":"EV/EBITDA"},"def":{"en":"Enterprise value (market cap plus debt minus cash) divided by EBITDA. A valuation measure that is neutral to debt levels.","hi":"उद्यम मूल्य (बाज़ार पूँजीकरण + कर्ज़ − नकद) ÷ EBITDA। कर्ज़ स्तर से स्वतंत्र वैल्यूएशन मापक।"}},{"cat":"fundamental","term":{"en":"PEG ratio","hi":"PEG अनुपात"},"def":{"en":"P/E ratio divided by the expected earnings growth rate. A rough guide to whether a growth stock is fairly priced.","hi":"P/E अनुपात ÷ अपेक्षित कमाई वृद्धि दर। ग्रोथ शेयर की उचित कीमत का मोटा मार्गदर्शक।"}},{"cat":"fundamental","term":{"en":"Discounted cash flow (DCF)","hi":"डिस्काउंटेड कैश फ़्लो (DCF)"},"def":{"en":"A valuation method that estimates future cash flows and discounts them to today's value.","hi":"भविष्य के कैश फ़्लो का अनुमान लगाकर उन्हें आज के मूल्य पर लाने वाला वैल्यूएशन तरीका।"}},{"cat":"fundamental","term":{"en":"Margin of safety","hi":"सुरक्षा मार्जिन (Margin of safety)"},"def":{"en":"The gap between estimated value and price. Buying with a margin protects you if your estimate is too optimistic.","hi":"अनुमानित मूल्य और कीमत के बीच का अंतर। अनुमान ज़्यादा आशावादी हो तो यह मार्जिन सुरक्षा देता है।"}}];
